import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.KxDd3USm.js";const d=JSON.parse('{"title":"06.8 课后考题","description":"","frontmatter":{},"headers":[],"relativePath":"06-计算机网络/90-课后考题.md","filePath":"06-计算机网络/90-课后考题.md"}'),p={name:"06-计算机网络/90-课后考题.md"};function e(g,t,a,_,C,P){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="_06-8-课后考题" tabindex="-1">06.8 课后考题 <a class="header-anchor" href="#_06-8-课后考题" aria-label="Permalink to &quot;06.8 课后考题&quot;">​</a></h1><p><strong>1.</strong> 能根据 IP 地址进行路径选择、连接不同网络并隔离广播域的网络设备是（）。 A. 集线器 B. 路由器 C. 二层交换机 D. 中继器</p><p><strong>2.</strong> SMTP、FTP、HTTP 等协议在 TCP/IP 体系结构中属于（）。 A. 应用层 B. 传输层 C. 网际层 D. 网络接口层</p><p><strong>3.</strong> 关于集线器与交换机，下列说法正确的是（）。 A. 两者都工作在物理层 B. 交换机能隔离冲突域，集线器不能 C. 两者都能隔离广播域 D. 交换机工作在网络层，依据 IP 地址转发</p><p><strong>4.</strong> 主机 IP 地址为 172.30.1.5，下列说法正确的是（）。 A. A 类公网地址 B. B 类私网地址 C. C 类公网地址 D. B 类公网地址</p><p><strong>5.</strong> 下列 IP 地址中，属于私网地址的是（）。 A. 172.32.10.1 B. 192.169.1.5 C. 10.255.255.1 D. 169.254.5.1</p><p><strong>6.</strong> 某子网的子网掩码为 255.255.255.240（/28），该子网最多可接入的主机数为（）。 A. 16 B. 14 C. 12 D. 30</p><p><strong>7.</strong> 主机地址为 192.168.10.37，子网掩码为 255.255.255.240，该主机所在子网的网络地址是（）。 A. 192.168.10.16 B. 192.168.10.32 C. 192.168.10.48 D. 192.168.10.0</p><p><strong>8.</strong> 将 B 类网络 172.16.0.0/16 划分子网，要求划分出至少 6 个子网、每个子网至少容纳 25 台主机，并使每个子网的可用主机数尽可能多，应选用的子网掩码是（）。 A. 255.255.192.0 B. 255.255.224.0 C. 255.255.240.0 D. 255.255.248.0</p><p><strong>9.</strong> 将 192.168.4.0/24、192.168.5.0/24、192.168.6.0/24、192.168.7.0/24 四个网段聚合，得到的超网地址是（）。 A. 192.168.4.0/22 B. 192.168.5.0/22 C. 192.168.4.0/23 D. 192.168.0.0/21</p><p><strong>10.</strong> 关于 UDP 协议，下列说法正确的是（）。 A. 面向连接，提供可靠传输 B. 无连接，不保证可靠交付，传输开销小 C. 提供流量控制和拥塞控制 D. 保证数据按发送顺序到达</p><p><strong>11.</strong> TCP 和 UDP 两种协议均具备的能力是（）。 A. 连接建立与管理 B. 出错重传 C. 流量控制 D. 通过端口号标识上层应用</p><p><strong>12.</strong> TCP 建立连接的三次握手中，客户端发出的第一个报文是（）。 A. ACK 报文 B. FIN 报文 C. SYN 报文 D. SYN+ACK 报文</p><p><strong>13.</strong> 下列协议与默认端口的对应关系中，错误的是（）。 A. FTP — 21 B. HTTP — 80 C. SMTP — 110 D. TELNET — 23</p><p><strong>14.</strong> DHCP 协议的主要功能是（）。 A. 将域名解析为 IP 地址 B. 为主机自动分配 IP 地址、子网掩码、默认网关等网络配置 C. 在邮件服务器之间传递电子邮件 D. 加密传输网页数据</p><p><strong>15.</strong> 在 HTML 文档中，用于建立超链接的标签是（）。 A. <code>&lt;p&gt;</code> B. <code>&lt;img&gt;</code> C. <code>&lt;br&gt;</code> D. <code>&lt;a&gt;</code></p><p><strong>案例风格题（按大题节奏作答，写出过程）</strong></p><p><strong>案例 1.</strong> 某公司分得一个 C 类网段 192.168.100.0/24，需要划分为 4 个部门子网，且每个部门的主机数不超过 50 台。请回答： (1) 求每个子网的子网掩码（用点分十进制表示）； (2) 依次写出 4 个子网的网络地址，并给出每个子网的可用主机数； (3) 写出第 3 个子网（按 (2) 中顺序数第 3 个）的广播地址与可用主机地址范围。</p><hr>',19)])])}const A=o(p,[["render",e]]);export{d as __pageData,A as default};
